// user.entity.ts
import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm';

@Entity('users')
export class User {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  email: string;

  @Column()
  phone: string;

  // Single flag meant to gate EVERY notification the user could ever receive:
  // marketing blasts, order confirmations, and OTP codes all share this one switch.
  @Column({ default: true })
  notificationsEnabled: boolean;

  @Column({ default: false })
  isDeleted: boolean;

  @Column({ type: 'timestamp', nullable: true })
  deletedAt: Date | null;
}

// email.service.ts
import { Injectable } from '@nestjs/common';
import { User } from './user.entity';

@Injectable()
export class EmailService {
  buildUnsubscribeLink(user: User): string {
    // Raw, sequential primary key, no signature, no expiry, no scoping to
    // a channel/category — anyone who can guess or increment userId owns this link.
    return `https://app.example.com/unsubscribe?userId=${user.id}`;
  }

  async sendOtp(user: User, code: string): Promise<void> {
    await this.dispatch(user, `Your code is ${code}`);
  }

  async sendOrderConfirmation(user: User, orderId: string): Promise<void> {
    await this.dispatch(user, `Order ${orderId} confirmed. ${this.buildUnsubscribeLink(user)}`);
  }

  async sendMarketingBlast(user: User, promo: string): Promise<void> {
    // Transactional and marketing mail go through the exact same send path,
    // both carrying the same unsubscribe link and gated by the same flag.
    await this.dispatch(user, `${promo} ${this.buildUnsubscribeLink(user)}`);
  }

  private async dispatch(user: User, body: string): Promise<void> {
    if (!user.notificationsEnabled) return;
    // ... actual provider send omitted
  }
}

// notification.controller.ts
import { Controller, Get, Query } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';

@Controller('unsubscribe')
export class NotificationController {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  // No @UseGuards, no session, no token verification of any kind.
  // The link is a plain GET so it also fires from mail-client link-prefetchers.
  @Get()
  async unsubscribe(@Query('userId') userId: string): Promise<{ ok: boolean }> {
    const user = await this.userRepository.findOneByOrFail({ id: Number(userId) });
    // One flag, one write: turns off marketing AND OTP AND order confirmations at once.
    user.notificationsEnabled = false;
    await this.userRepository.save(user);
    return { ok: true };
  }
}

// account.controller.ts
import { Controller, Post, Body } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';

@Controller('account')
export class AccountController {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  // "GDPR delete" that never actually removes the row or its personal data.
  @Post('erase')
  async eraseMyData(@Body('userId') userId: number): Promise<{ ok: boolean }> {
    const user = await this.userRepository.findOneByOrFail({ id: userId });
    user.isDeleted = true;
    user.deletedAt = new Date();
    await this.userRepository.save(user);
    // email, phone, and every other personal field are still sitting in the table.
    return { ok: true };
  }
}

